package com.bank.helm;

import java.math.BigDecimal;

public class Account {
    private final String accountId; private final String holderName; private BigDecimal balance;
    public Account(String id, String name, BigDecimal bal) { accountId=id; holderName=name; balance=bal; }
    public void debit(BigDecimal a) { balance = balance.subtract(a); }
