package com.bank.helm;

import java.util.*;
import java.util.logging.Logger;

// Models helm: render templates with layered values, track revisions, rollback.
public class HelmEngine {
    private static final Logger log = Logger.getLogger(HelmEngine.class.getName());
    private final String chartVersion;
    private final Map<String,String> baseValues;
    private final List<Release> history = new ArrayList<>();

    public HelmEngine(String chartVersion, Map<String,String> baseValues) {
            this.chartVersion = chartVersion;
            this.baseValues = baseValues;
    }

    // Overlay env values on base, then render the Deployment template.
    private Map<String,String> merge(Map<String,String> overrides) {
            Map<String,String> v = new HashMap<>(baseValues); v.putAll(overrides);
            return v;
    }
    private String render(String releaseName, Map<String,String> v) {
        return "Deployment " + releaseName + "-transfer replicas=" + v.get("replicaCount")
                + " image=" + v.get("image") + " dbHost=" + v.get("dbHost");
    }

    public void install(String releaseName, Map<String,String> overrides) {
        Map<String,String> v = merge(overrides);
        String manifest = render(releaseName, v);
        history.add(new Release(1, chartVersion, v, manifest, "deployed"));
        log.info(() -> "install " + releaseName + " rev=1 -> " + manifest);
    }

    // upgrade with optional --atomic: failed upgrade auto-rolls back.
    public void upgrade(String releaseName, Map<String,String> overrides, boolean healthy, boolean atomic) {
        Map<String,String> v = merge(overrides);
        String manifest = render(releaseName, v);
        int rev = history.size() + 1;
        if (!healthy) {
            log.severe(() -> "upgrade rev=" + rev + " FAILED health check");
            if (atomic) { log.warning("--atomic: auto rollback to last good revision"); rollback(releaseName, history.size()); return; }
            history.add(new Release(rev, chartVersion, v, manifest, "failed"));
            return;
        }
        history.add(new Release(rev, chartVersion, v, manifest, "deployed"));
        log.info(() -> "upgrade " + releaseName + " rev=" + rev + " -> " + manifest);
    }

    public void rollback(String releaseName, int toRevision) {
        Release target = history.get(toRevision - 1);
        int rev = history.size() + 1;
        history.add(new Release(rev, target.chartVersion, target.values, target.renderedManifest, "deployed"));
        log.warning(() -> "rollback " + releaseName + " to rev=" + toRevision
                + " (new rev=" + rev + ") -> " + target.renderedManifest);
    }

    public void printHistory() {
        history.forEach(r -> log.info("  rev=" + r.revision + " chart=" + r.chartVersion
                + " status=" + r.status + " | " + r.renderedManifest));
    }
}
