package com.bank.helm;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class HelmDemo {
    private static final Logger log = Logger.getLogger(HelmDemo.class.getName());
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler(); h.setFormatter(new BankLogFormatter()); h.setLevel(Level.ALL);
        Logger root = Logger.getLogger(""); root.addHandler(h); root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));

        Map<String,String> base = new HashMap<>(Map.of(
                "replicaCount", "2", "image", "nbi/transfer-service:v7", "dbHost", "dev-db.internal"));
        HelmEngine helm = new HelmEngine("1.4.0", base);

        // Dev install (defaults)
        helm.install("transfer-dev", Map.of());

        // Production install (overlay prod values)
        Map<String,String> prod = Map.of("replicaCount", "10", "dbHost", "prod-db.internal");
        helm.install("transfer-prod", prod);
        log.info("prod live; a transfer runs");
        rajesh.debit(new BigDecimal("50000")); priya.credit(new BigDecimal("50000"));

        // Bad prod upgrade with --atomic -> auto rollback
        helm.upgrade("transfer-prod", Map.of("replicaCount", "10", "image", "nbi/transfer-service:v8-bad",
                "dbHost", "prod-db.internal"), false, true);

        helm.printHistory();
    }
}
